namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough.\n3. Spread crushed tomatoes.\n4. Add torn mozzarella.\n5. Bake 10-12 minutes.\n6. Top with fresh basil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or pan-fry chicken.\n3. Sauté onion, garlic, ginger.\n4. Add tomato sauce and spices.\n5. Simmer with cream.\n6. Add chicken and serve with rice.", AverageRating = 4.8, RatingCount = 24 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef.\n2. Add taco seasoning and water.\n3. Simmer until thickened.\n4. Warm taco shells.\n5. Assemble with toppings.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Shrimp, Egg, Bean sprouts, Peanuts, Tamarind paste, Fish sauce, Lime", Steps = "1. Soak rice noodles.\n2. Stir-fry shrimp.\n3. Push aside, scramble egg.\n4. Add noodles and sauce.\n5. Toss with bean sprouts.\n6. Garnish with peanuts and lime.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour", Steps = "1. Melt chocolate and butter.\n2. Whisk eggs and sugar.\n3. Fold in chocolate mixture.\n4. Add flour.\n5. Bake at 425°F for 12 minutes.\n6. Invert onto plate and serve immediately.", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 6, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti al dente.\n2. Crisp guanciale in a pan.\n3. Mix eggs and grated pecorino.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, add egg mixture.\n6. Season with black pepper.", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Add lime juice and salt.\n4. Fold in diced onion, tomato, jalapeño.\n5. Top with cilantro.\n6. Serve with tortilla chips.", AverageRating = 4.4, RatingCount = 10 },
        new Recipe { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfingers, Mascarpone, Espresso, Eggs, Sugar, Cocoa powder", Steps = "1. Brew espresso and cool.\n2. Whisk egg yolks with sugar.\n3. Fold in mascarpone.\n4. Whip egg whites and fold in.\n5. Dip ladyfingers in espresso.\n6. Layer with cream, repeat.\n7. Dust with cocoa.", AverageRating = 4.8, RatingCount = 22 },
    };

    private readonly List<RecipeCategory> _categories = new()
    {
        new RecipeCategory { Name = "Italian", Description = "Classic Italian dishes from pasta to pizza", Icon = "🇮🇹" },
        new RecipeCategory { Name = "Mexican", Description = "Bold flavors from south of the border", Icon = "🇲🇽" },
        new RecipeCategory { Name = "Indian", Description = "Rich spices and aromatic curries", Icon = "🇮🇳" },
        new RecipeCategory { Name = "Asian", Description = "Stir-fries, noodles, and more", Icon = "🥢" },
        new RecipeCategory { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
    };

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

