@page "/recipes/{CategoryName}/{RecipeId:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="meta">Category: @Recipe.Category | ⭐ @Recipe.AverageRating (@Recipe.RatingCount ratings)</p>

    <section>
        <h2>Ingredients</h2>
        <ul>
            @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section>
        <h2>Steps</h2>
        @foreach (var step in Recipe.Steps.Split('\n'))
        {
            <p>@step</p>
        }
    </section>

    <section class="rating-section">
        <h2>Rate this Recipe</h2>
        <StarRating RecipeId="Recipe.Id" />
