toolArgs.file_text:
@using RecipeCommunity.Services
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star @(star <= SelectedRating ? "filled" : "")"
                @onclick="() => Rate(star)"
                disabled="@HasRated">
            @(star <= SelectedRating ? "★" : "☆")
        </button>
    }
    @if (HasRated)
    {
        <span class="confirmation">Thanks! You rated @SelectedRating star@(SelectedRating != 1 ? "s" : "").</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating { get; set; }
    private bool HasRated { get; set; }

    private void Rate(int stars)
    {
        if (HasRated) return;
        SelectedRating = stars;
        HasRated = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

