toolArgs.file_text:
@page "/submit"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@using Microsoft.AspNetCore.Components.Forms
@rendermode InteractiveServer

<PageTitle>Submit Recipe - Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>

@if (Submitted)
{
    <div class="success-message">
        <h2>🎉 Recipe Submitted!</h2>
        <p>Your recipe "<strong>@Model.Title</strong>" has been added to the @Model.Category category.</p>
        <a href="/recipes/@Model.Category.ToLower()">View @Model.Category recipes</a>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="Model.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="Model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Name</option>
                }
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" @bind-Value="Model.Ingredients" rows="4"
                           placeholder="Flour, Sugar, Butter, Apples, Cinnamon" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Model.Steps" rows="6"
                           placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. ..." />
        </div>

        <button type="submit" class="submit-btn">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel Model { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = Model.Title,
            Category = Model.Category,
            Ingredients = Model.Ingredients,
            Steps = Model.Steps
        };
        RecipeService.AddRecipe(recipe);
        Submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

