    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.4rem;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
    box-sizing: border-box;
}

.submit-btn {
    background: #2d6a4f;
    color: white;
    border: none;
    padding: 0.75rem 2rem;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
}

.submit-btn:hover {
    background: #1b4332;
}

.success-message {
    padding: 2rem;
    background: #d4edda;
    border-radius: 8px;
    border: 1px solid #c3e6cb;
}

.success-message a {
    color: #2d6a4f;
    font-weight: 600;
}

